        // MARK: - About Window & Brand Lore (v1.0.0 Production Release)
        .aboutWindowTitle: Translation(english: "About OtterKeep", hungarian: "Az OtterKeep névjegye"),
        .aboutTagline: Translation(english: "Keep what you love close to your chest.", hungarian: "Őrizd a legfontosabb kincseidet biztos kezekben."),
        .aboutLoreTitle: Translation(english: "The Legend of the Favorite Pebble", hungarian: "A vidrák kedvenc kavicsának legendája"),
        .aboutLoreStory: Translation(english: "Sea otters have an extraordinary, instinctive ritual: throughout their entire lives, they carry their most prized favorite pebble tucked securely into a hidden pocket of skin beneath their forearms. They use it to open shells, play with it while floating on the waves, and never let it go under any circumstances. OtterKeep protects the files, historical snapshots, and precious memories on your Mac with that exact same tender vigilance and devotion.", hungarian: "A tengeri vidráknak van egy különleges, ösztönös szokásuk: egész életükben a hónuk alatt lévő rejtett kis bőrredőben őrzik a kedvenc kavicsukat. Ezzel nyitják fel a kagylókat, játszanak vele a hullámok hátán lebegve, és soha, semmilyen körülmények között nem hagyják el. Az OtterKeep ugyanezzel a féltő gondoskodással vigyáz a Mac-eden lévő fájlokra, pillanatképekre és emlékekre."),
        .aboutReleaseHighlightsTitle: Translation(english: "What's New in Version 1.1.0", hungarian: "Újdonságok az 1.1.0-ás kiadásban"),
        .aboutHighlight1: Translation(english: "Native APFS Copy-on-Write engine with instant zero-cost snapshot creation", hungarian: "Natív APFS Copy-on-Write motor zéró redundanciájú, azonnali pillanatképekkel"),
        .aboutHighlight2: Translation(english: "Apple Photos library sync with intelligent iCloud eviction safeguard", hungarian: "Apple Fotótár mentés intelligens iCloud helyfelszabadítási védelemmel"),
        .aboutHighlight3: Translation(english: "3-2-1 backup compliance with client-side AES-256 encrypted S3, SFTP, and WebDAV replication", hungarian: "3-2-1 mentési megfelelőség kliensoldali AES-256 titkosított S3, SFTP és WebDAV replikációval"),
        .aboutHighlight4: Translation(english: "Proactive Ransomware & Anomaly Shield preventing compromised snapshots", hungarian: "Proaktív zsarolóvírus- és anomáliavédelem a sérült mentések megakadályozására"),
        .aboutHighlight5: Translation(english: "Finder menu integration and interactive Time Machine restoration with QuickLook preview", hungarian: "Finder menü integráció és interaktív időkapszula-visszaállítás QuickLook előnézettel"),
        .aboutVersionInfoFormat: Translation(english: "Version %@ (Build %@) • Production Release", hungarian: "%@ verzió (%@ build) • Végleges kiadás"),
        .aboutCopyright: Translation(english: "© 2024–2026 Richard Eszes & OtterKeep Contributors. MIT License.", hungarian: "© 2024–2026 Eszes Richárd és az OtterKeep közreműködői. MIT Licenc."),
        .aboutArchitectureTag: Translation(english: "Apple Silicon & Intel Universal 64-bit", hungarian: "Apple Silicon & Intel Univerzális bináris"),
        .aboutLinksTitle: Translation(english: "Community & Support", hungarian: "Közösség és támogatás"),
        .aboutWebsiteButton: Translation(english: "Project Homepage", hungarian: "Projekt weboldal"),
        .aboutDocumentationButton: Translation(english: "User Guides & Docs", hungarian: "Felhasználói kézikönyv"),
        .aboutReleaseNotesButton: Translation(english: "Release Notes", hungarian: "Kiadási jegyzék"),
        .aboutCloseButton: Translation(english: "Close", hungarian: "Bezárás"),
        // MARK: - Modern UI Tooltips & Feature Badges
        .tooltipStartBackup: Translation(english: "Execute an incremental APFS snapshot backup now", hungarian: "Inkrementális APFS pillanatkép-mentés azonnali indítása"),
        .tooltipDryRun: Translation(english: "Analyze changes and estimate required storage without writing any data to disk", hungarian: "Változások elemzése és tárhelybecslés tényleges lemezre írás nélkül"),
        .tooltipStopBackup: Translation(english: "Safely abort the ongoing backup operation", hungarian: "A folyamatban lévő mentési művelet biztonságos leállítása"),
        .tooltipApfsCow: Translation(english: "Uses macOS APFS Copy-on-Write cloning. Identical blocks share physical disk space with zero duplicate overhead.", hungarian: "macOS APFS Copy-on-Write klónozást használ. Az azonos blokkok zéró duplikációval osztoznak a lemezterületen."),
        .tooltip321Rule: Translation(english: "3 copies of your data on 2 different media types, with 1 copy stored offsite or in the cloud.", hungarian: "3 példány az adataidból, 2 különféle médiatípuson, 1 példány távoli vagy felhős helyszínen."),
        .tooltipRansomwareShield: Translation(english: "Monitors rate of file changes and halts backup if sudden mass encryption or file deletions are detected.", hungarian: "Figyeli a fájlváltozások arányát, és azonnal leállítja a mentést hirtelen tömeges titkosítás vagy törlés esetén."),
        .tooltipICloudEviction: Translation(english: "Downloads iCloud-only photos temporarily for backup, then evicts local cache so your disk never fills up.", hungarian: "Ideiglenesen letölti a csak felhőben lévő fotókat a mentéshez, majd kiüríti a helyi gyorsítótárat a tárhely védelmére."),
        .tooltipStorageForecast: Translation(english: "Predicts destination disk depletion date based on historical daily data growth rates.", hungarian: "Megbecsli a céllemez megtelésének várható dátumát a korábbi napi adattömeg-növekedés alapján."),
        .tooltipVolumeMount: Translation(english: "Automatically triggers this backup profile whenever the external destination volume is plugged in.", hungarian: "Automatikusan elindítja ezt a mentési profilt, amint a külső célmeghajtót csatlakoztatod."),
        .tooltipAutoEject: Translation(english: "Safely unmounts and ejects the destination disk after backup completion to prevent accidental disconnects.", hungarian: "A mentés befejezése után biztonságosan leválasztja és kiadja a céllemezt a véletlen lecsatlakoztatás elkerülésére."),
        .tooltipFinderSync: Translation(english: "Integrates right-click version restore and snapshot badges directly into macOS Finder.", hungarian: "Közvetlenül a macOS Finderbe építi a jobb klikkes verzióvisszaállítást és a mentési jelvényeket."),
        .tooltipWebhookAlerts: Translation(english: "Pushes real-time alerts to Slack, Discord, Pushover, or custom endpoints upon backup completion.", hungarian: "Valós idejű értesítéseket küld Slack, Discord, Pushover vagy egyéni végpontokra a mentés befejezésekor."),
        .tooltipZstdPackaging: Translation(english: "Streams files into a single compressed archive to drastically reduce API overhead and cloud storage fees.", hungarian: "Egyetlen tömörített archívumba csomagolja a fájlokat, drasztikusan csökkentve az API hívások számát és a felhőtárhely díját."),
        .tooltipQuickLook: Translation(english: "Press Spacebar to preview the selected file version instantly using macOS QuickLook.", hungarian: "Nyomd le a Szóközt a kijelölt fájlverzió azonnali megtekintéséhez a macOS QuickLook segítségével."),
        // MARK: - Actionable Guidance & Permission Errors
        .errFDAInstructionTitle: Translation(english: "Full Disk Access (FDA) Required", hungarian: "Teljes lemezhozzáférés (FDA) szükséges"),
        .errFDAInstructionDesc: Translation(english: "macOS requires explicit permission to back up protected folders such as Documents, Desktop, and Mail. Open System Settings > Privacy & Security > Full Disk Access and enable OtterKeep.", hungarian: "A macOS kifejezett engedélyt kér a védett mappák (pl. Dokumentumok, Íróasztal, Mail) mentéséhez. Nyisd meg a Rendszerbeállítások > Adatvédelem és biztonság > Teljes lemezhozzáférés menüpontot, és engedélyezd az OtterKeep alkalmazást."),
        .errDiskFullRemediationDesc: Translation(english: "The destination volume does not have enough free space to complete this snapshot. Run storage maintenance to prune older snapshots or attach a larger drive.", hungarian: "A célköteten nincs elegendő szabad hely a mentés befejezéséhez. Futtass tárhely-karbantartást a régi mentések ritkításához, vagy csatlakoztass egy nagyobb kapacitású meghajtót."),
        .errRemoteUnreachableRemediationDesc: Translation(english: "Unable to establish connection to the remote backup endpoint. Verify your network connection, credentials, and firewall settings.", hungarian: "Nem sikerült kapcsolatot létesíteni a távoli mentési végponttal. Ellenőrizd az internetkapcsolatot, a hozzáférési adatokat és a hálózati tűzfalbeállításokat."),
        .errPhotosNotAuthorizedTitle: Translation(english: "Photos Access Restricted", hungarian: "Fotótár-hozzáférés korlátozva"),
        .errPhotosNotAuthorizedDesc: Translation(english: "OtterKeep needs permission to access your Apple Photos Library to perform incremental backups. Enable access in System Settings > Privacy & Security > Photos.", hungarian: "Az OtterKeep számára engedély szükséges az Apple Fotótárhoz az inkrementális mentés elvégzéséhez. Engedélyezd a hozzáférést a Rendszerbeállítások > Adatvédelem és biztonság > Fotók menüpontban."),
